import "./Post.css"

function Post(props) {
    return (
        <div className="single-post">
            <h2>{props.restaurant}</h2>
            <h3>{props.eat_time}</h3>
            <h3>{props.max_party}</h3>
            <h3>{props.host}</h3>
        </div>
    )
}

export default Post
